// ============================================================================
// ROUTING POLICY: the node for HOW requests are routed. DATA ONLY (no logic).
// Edit the values between the EDIT lines. Every request is checked against it, and a mistake
// gives a clear 500 (router_misconfigured, lines start "Policy:") before any provider is called.
// What you cannot change here, on purpose: a task_type sent by the caller always wins, only
// tiers that exist in CONFIG.TIERS_JSON can be used, budgets / breakers / cache / quality
// checks always apply, and a policy can only make limits tighter than CONFIG.
// ============================================================================
// ---- EDIT FROM HERE ---------------------------------------------------------
const policy = {
  // When the caller sends NO task_type, guess one from the prompt. The first rule that matches wins.
  // A rule: { task_type, contains_any: ['text', ...] (any, ignoring case), min_chars, max_chars }
  // (every condition you give must hold; give at least one).
  classify: [
    // { task_type: 'code', contains_any: ['def ', 'function ', 'stack trace'] },
    // { task_type: 'complex', min_chars: 2000 },
  ],
  // Used when the caller sends none and no rule matches: 'simple', 'code' or 'complex'.
  default_task_type: 'simple',

  // Added first to the system message of EVERY request (optional).
  system: '',

  // Per task type (simple / code / complex). Everything is optional.
  //   tiers:            use ONLY these tiers, in THIS order (names from CONFIG.TIERS_JSON)
  //   max_tokens:       the answer length used when the caller sends none
  //   max_tokens_limit: callers asking for more get a 400 (must not exceed CONFIG.MAX_ALLOWED_TOKENS)
  //   system:           extra system message for this type
  //   require_json:     true = always demand JSON for this type (it cannot be turned off here)
  by_task_type: {
    // complex: { tiers: ['premium'], max_tokens: 2048, max_tokens_limit: 4096, system: 'You are a careful analyst.', require_json: true },
  },
};
// ---- STOP EDITING HERE ------------------------------------------------------
const pick = (o, k, d) => (o && o[k] !== undefined && o[k] !== null ? o[k] : d);
const norm = { classify: pick(policy, 'classify', []), default_task_type: pick(policy, 'default_task_type', 'simple'), system: pick(policy, 'system', ''), by_task_type: pick(policy, 'by_task_type', {}),
  _is_obj: policy !== null && typeof policy === 'object' && !Array.isArray(policy), _raw_keys: Object.keys(policy || {}) };
return [{ json: { ...$input.first().json, policy: norm } }];

const C = $('CONFIG').first().json;
const req = $('LLM Request Webhook').first().json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const reject = (status, error, details) => [{ json: { ok: false, http_status: status, response_body: { error, ...(details ? { details } : {}) }, notifications: [] } }];

if (C.ROUTER_AUTH_TOKEN && (req.headers || {})['x-router-token'] !== C.ROUTER_AUTH_TOKEN) return reject(401, 'unauthorized');

// ---- CONFIG sanity: say what is wrong now, not three nodes later
const bad = [];
const url = (v) => /^https?:\/\//.test(v || '');
if (C.CACHE_ENABLED && !url(C.CACHE_API_URL)) bad.push('CONFIG.CACHE_API_URL must start with http(s):// (or set CACHE_ENABLED=false)');
if (C.BREAKER_ENABLED && !url(C.BREAKER_API_URL)) bad.push('CONFIG.BREAKER_API_URL must start with http(s):// (or set BREAKER_ENABLED=false)');
if (C.BUDGET_ENABLED && !url(C.BUDGET_API_URL)) bad.push('CONFIG.BUDGET_API_URL must start with http(s):// (or set BUDGET_ENABLED=false)');
if (C.SLACK_WEBHOOK_URL && !url(C.SLACK_WEBHOOK_URL)) bad.push('CONFIG.SLACK_WEBHOOK_URL must be blank or start with http(s)://');
try { if (!isObj(JSON.parse(C.SERVICE_HEADERS_JSON || '{}'))) throw 0; } catch (e) { bad.push('CONFIG.SERVICE_HEADERS_JSON must be a JSON object'); }
if (!['open', 'closed'].includes(C.BUDGET_FAIL_MODE)) bad.push("CONFIG.BUDGET_FAIL_MODE must be 'open' or 'closed'");
const num = (k) => Number(C[k]);
for (const k of ['CACHE_TTL_SECONDS', 'BREAKER_FAILURE_THRESHOLD', 'BREAKER_COOLDOWN_SECONDS', 'BREAKER_MAX_COOLDOWN_SECONDS', 'PROBE_CLAIM_TTL_SECONDS', 'MAX_PROMPT_CHARS', 'DEFAULT_MAX_TOKENS', 'MAX_ALLOWED_TOKENS', 'REQUEST_TIMEOUT_MS', 'ALERT_COOLDOWN_SECONDS']) if (!(num(k) > 0)) bad.push(`CONFIG.${k} must be a number > 0`);
if (!(num('DAILY_BUDGET_USD') >= 0)) bad.push('CONFIG.DAILY_BUDGET_USD must be a number >= 0');
if (!(num('RETRIES_PER_TIER') >= 0 && Number.isInteger(num('RETRIES_PER_TIER')))) bad.push('CONFIG.RETRIES_PER_TIER must be an integer >= 0');
if (!(num('RETRY_BACKOFF_MS') >= 0)) bad.push('CONFIG.RETRY_BACKOFF_MS must be a number >= 0 (0 = retry at once)');
if (!(num('RETRY_BACKOFF_MAX_MS') >= num('RETRY_BACKOFF_MS'))) bad.push('CONFIG.RETRY_BACKOFF_MAX_MS must be a number >= RETRY_BACKOFF_MS');
if (!(num('RETRY_JITTER_PERCENT') >= 0 && num('RETRY_JITTER_PERCENT') <= 100)) bad.push('CONFIG.RETRY_JITTER_PERCENT must be a number from 0 to 100');
if (!(num('RETRY_MAX_TOTAL_WAIT_MS') >= 0)) bad.push('CONFIG.RETRY_MAX_TOTAL_WAIT_MS must be a number >= 0');
if (typeof C.RETRY_HONOUR_RETRY_AFTER !== 'boolean') bad.push('CONFIG.RETRY_HONOUR_RETRY_AFTER must be true or false');
if (!(num('MIN_RESPONSE_CHARS') >= 0)) bad.push('CONFIG.MIN_RESPONSE_CHARS must be a number >= 0');
if (num('DEFAULT_MAX_TOKENS') > num('MAX_ALLOWED_TOKENS')) bad.push('CONFIG.DEFAULT_MAX_TOKENS must not exceed MAX_ALLOWED_TOKENS');

const TASKS = ['simple', 'code', 'complex'], KINDS = ['ollama', 'openai', 'anthropic'];
let tiers = [];
try {
  const raw = JSON.parse(C.TIERS_JSON);
  if (!Array.isArray(raw) || raw.length === 0) throw new Error('TIERS_JSON must be a non-empty JSON array');
  const seen = new Set();
  raw.forEach((t, i) => {
    const w = `TIERS_JSON[${i}]`;
    if (!isObj(t)) { bad.push(`${w} must be an object`); return; }
    if (typeof t.name !== 'string' || !/^[A-Za-z0-9._-]{1,64}$/.test(t.name)) bad.push(`${w}.name must be 1-64 characters: letters, digits and . _ -`);
    else if (seen.has(t.name)) bad.push(`${w}.name "${t.name}" is used twice`); else seen.add(t.name);
    if (!KINDS.includes(t.kind)) bad.push(`${w}.kind must be one of ${KINDS.join(', ')}`);
    if (!url(t.url)) bad.push(`${w}.url must be the full endpoint URL, starting with http(s)://`);
    if (typeof t.model !== 'string' || !t.model) bad.push(`${w}.model must be a non-empty string`);
    const handles = t.handles === undefined ? TASKS : t.handles;
    if (!Array.isArray(handles) || !handles.length || handles.some((h) => !TASKS.includes(h))) bad.push(`${w}.handles must be a non-empty array of ${TASKS.join('|')}`);
    const paid = t.paid === true;
    const pin = t.price_in_per_mtok === undefined ? 0 : Number(t.price_in_per_mtok), pout = t.price_out_per_mtok === undefined ? 0 : Number(t.price_out_per_mtok);
    if (!(pin >= 0) || !(pout >= 0)) bad.push(`${w} prices must be numbers >= 0 (USD per million tokens)`);
    const timeout = t.timeout_ms === undefined ? 30000 : Number(t.timeout_ms);
    if (!(timeout > 0 && timeout <= 600000)) bad.push(`${w}.timeout_ms must be a number between 1 and 600000`);
    if (t.headers !== undefined && !isObj(t.headers)) bad.push(`${w}.headers must be an object`);
    tiers.push({ name: t.name, kind: t.kind, url: t.url, model: t.model, handles, paid, price_in: pin, price_out: pout, timeout_ms: timeout,
      api_key: typeof t.api_key === 'string' ? t.api_key : '', headers: isObj(t.headers) ? t.headers : {}, anthropic_version: t.anthropic_version || '2023-06-01' });
  });
} catch (e) { bad.push('CONFIG.TIERS_JSON is not valid: ' + e.message); }
// ---- the Routing Policy node
{
  const PL = $('Routing Policy').first().json.policy;
  const pb = (m) => bad.push('Policy: ' + m);
  const names = tiers.map((t) => t.name);
  const str = (v, min, max) => typeof v === 'string' && v.length >= min && v.length <= max;
  const maxAllowed = Number(C.MAX_ALLOWED_TOKENS);
  if (!PL._is_obj) pb('policy must be an object');
  else {
    for (const k of PL._raw_keys) if (!['classify', 'default_task_type', 'system', 'by_task_type'].includes(k)) pb(`${k} is not a known setting (classify, default_task_type, system, by_task_type)`);
    if (!TASKS.includes(PL.default_task_type)) pb(`default_task_type must be one of ${TASKS.join(', ')}`);
    if (!str(PL.system, 0, 2000)) pb('system must be text of at most 2000 characters');
    if (!Array.isArray(PL.classify) || PL.classify.length > 20) pb('classify must be a list of at most 20 rules');
    else PL.classify.forEach((r, i) => {
      const w = `classify[${i}]`;
      if (!isObj(r)) { pb(`${w} must be an object`); return; }
      for (const k of Object.keys(r)) if (!['task_type', 'contains_any', 'min_chars', 'max_chars'].includes(k)) pb(`${w}.${k} is not a known setting (task_type, contains_any, min_chars, max_chars)`);
      if (!TASKS.includes(r.task_type)) pb(`${w}.task_type must be one of ${TASKS.join(', ')}`);
      if (r.contains_any !== undefined && !(Array.isArray(r.contains_any) && r.contains_any.length >= 1 && r.contains_any.length <= 50 && r.contains_any.every((x) => str(x, 1, 100)))) pb(`${w}.contains_any must be a list of 1 to 50 texts`);
      if (r.min_chars !== undefined && !(Number.isInteger(r.min_chars) && r.min_chars >= 0)) pb(`${w}.min_chars must be a whole number >= 0`);
      if (r.max_chars !== undefined && !(Number.isInteger(r.max_chars) && r.max_chars >= 1)) pb(`${w}.max_chars must be a whole number >= 1`);
      if (r.contains_any === undefined && r.min_chars === undefined && r.max_chars === undefined) pb(`${w} needs at least one of contains_any, min_chars, max_chars`);
      if (Number.isInteger(r.min_chars) && Number.isInteger(r.max_chars) && r.min_chars > r.max_chars) pb(`${w}.min_chars must not be above max_chars`);
    });
    if (!isObj(PL.by_task_type)) pb('by_task_type must be an object');
    else for (const [tt, r] of Object.entries(PL.by_task_type)) {
      const w = `by_task_type.${tt}`;
      if (!TASKS.includes(tt)) { pb(`${w}: "${tt}" is not a task type (${TASKS.join(', ')})`); continue; }
      if (!isObj(r)) { pb(`${w} must be an object`); continue; }
      for (const k of Object.keys(r)) if (!['tiers', 'max_tokens', 'max_tokens_limit', 'system', 'require_json'].includes(k)) pb(`${w}.${k} is not a known setting (tiers, max_tokens, max_tokens_limit, system, require_json)`);
      if (r.tiers !== undefined) {
        if (!(Array.isArray(r.tiers) && r.tiers.length >= 1 && new Set(r.tiers).size === r.tiers.length && r.tiers.every((n) => names.includes(n)))) pb(`${w}.tiers must be a list of different tier names from TIERS_JSON (known tiers: ${names.join(', ')})`);
        else if (!r.tiers.some((n) => tiers.find((t) => t.name === n).handles.includes(tt))) pb(`${w}.tiers: none of these tiers handles "${tt}" requests`);
      }
      for (const k of ['max_tokens', 'max_tokens_limit']) if (r[k] !== undefined && !(Number.isInteger(r[k]) && r[k] >= 1 && r[k] <= maxAllowed)) pb(`${w}.${k} must be a whole number from 1 to MAX_ALLOWED_TOKENS (${maxAllowed})`);
      if (Number.isInteger(r.max_tokens) && Number.isInteger(r.max_tokens_limit) && r.max_tokens > r.max_tokens_limit) pb(`${w}.max_tokens must not be above max_tokens_limit`);
      if (r.system !== undefined && !str(r.system, 1, 2000)) pb(`${w}.system must be 1 to 2000 characters`);
      if (r.require_json !== undefined && r.require_json !== true) pb(`${w}.require_json may only be true (a policy can turn JSON on, never off)`);
    }
  }
}
if (bad.length) return reject(500, 'router_misconfigured', bad);

// ---- request shape
if (!isObj(req.body)) return reject(400, 'validation_failed', ['body must be a JSON object']);
const b = req.body, errors = [];
if (typeof b.prompt !== 'string' || !b.prompt.trim()) errors.push('prompt is required and must be a non-empty string');
else if (b.prompt.length > num('MAX_PROMPT_CHARS')) errors.push(`prompt must be at most ${num('MAX_PROMPT_CHARS')} characters`);
const PL = $('Routing Policy').first().json.policy;
let task_type = b.task_type;
if (task_type === undefined || task_type === null) {
  task_type = PL.default_task_type;                                    // only when the caller sent none
  const low = typeof b.prompt === 'string' ? b.prompt.toLowerCase() : '';
  const hit = PL.classify.find((r) => (r.contains_any === undefined || r.contains_any.some((x) => low.includes(x.toLowerCase()))) && (r.min_chars === undefined || low.length >= r.min_chars) && (r.max_chars === undefined || low.length <= r.max_chars));
  if (hit) task_type = hit.task_type;
}
if (!TASKS.includes(task_type)) errors.push(`task_type must be one of ${TASKS.join(', ')}`);
const rule = (Object.prototype.hasOwnProperty.call(PL.by_task_type, task_type) ? PL.by_task_type[task_type] : {}) || {};
let max_tokens = rule.max_tokens || num('DEFAULT_MAX_TOKENS');
if (b.max_tokens !== undefined && b.max_tokens !== null) {
  if (!Number.isInteger(b.max_tokens) || b.max_tokens < 1 || b.max_tokens > num('MAX_ALLOWED_TOKENS')) errors.push(`max_tokens must be an integer between 1 and ${num('MAX_ALLOWED_TOKENS')}`);
  else if (rule.max_tokens_limit && b.max_tokens > rule.max_tokens_limit) errors.push(`max_tokens must be at most ${rule.max_tokens_limit} for ${task_type} requests`);
  else max_tokens = b.max_tokens;
}
let require_json = false;
if (b.require_json !== undefined && b.require_json !== null) { if (typeof b.require_json !== 'boolean') errors.push('require_json must be true or false'); else require_json = b.require_json; }
if (rule.require_json === true) require_json = true;
if (errors.length) return reject(400, 'validation_failed', errors);
const system = [PL.system, rule.system].filter((x) => x).join('\n\n');
const used_tiers = rule.tiers ? rule.tiers.map((n) => tiers.find((t) => t.name === n)) : tiers;

const est_in_tokens = Math.ceil((b.prompt.length + system.length + (require_json ? 90 : 0)) / 4);
// The cache key covers everything that changes the answer, including which models are configured.
const cache_material = JSON.stringify({ p: b.prompt, t: task_type, m: max_tokens, j: require_json, tiers: used_tiers.map((t) => `${t.name}|${t.kind}|${t.model}`), ...(system ? { s: system } : {}) });
return [{ json: { ok: true, plan: { request: { prompt: b.prompt, task_type, max_tokens, require_json, system }, tiers: used_tiers, est_in_tokens, cache_material } } }];

const C = $('CONFIG').first().json;
const P = $('Validate Request').first().json.plan;
const id = $('Request Id').first().json.request_id;
const miss = { json: { cache_hit: false, state: { next_idx: 0, attempts: [] } } };
if (!C.CACHE_ENABLED) return [miss];
const r = $input.first().json;
const entry = r.statusCode === 200 && r.body && typeof r.body === 'object' ? r.body : null;
const v = entry && entry.body && typeof entry.body === 'object' ? entry.body : null;
if (!v || typeof v.text !== 'string') return [miss];
const age = Date.now() - Number(entry.cached_at);
if (!Number.isFinite(age) || age < 0 || age >= C.CACHE_TTL_SECONDS * 1000) return [miss];      // the router enforces the TTL, the store need not
if (v.text.trim().length < C.MIN_RESPONSE_CHARS) return [miss];
let parsed;
if (P.request.require_json) { try { parsed = JSON.parse(v.text); } catch (e) { return [miss]; } }
const body = { request_id: id, text: v.text, task_type: P.request.task_type, provider: v.provider || 'cache', tier_index: v.tier_index === undefined ? null : v.tier_index, cached: true, cost_usd: 0 };
if (P.request.require_json) body.json = parsed;
return [{ json: { cache_hit: true, http_status: 200, response_body: body, notifications: [] } }];

const P = $('Validate Request').first().json.plan;
const inp = $input.first().json;
const st = inp.state || { next_idx: 0, attempts: [], waited_ms: 0 };
const attempts = [...st.attempts];
let idx = st.next_idx;
while (idx < P.tiers.length && !P.tiers[idx].handles.includes(P.request.task_type)) {
  attempts.push({ tier: P.tiers[idx].name, outcome: 'skipped', reason: 'task_type_not_handled' });
  idx++;
}
const out = { state: { next_idx: idx, attempts, waited_ms: st.waited_ms || 0 }, waits: [], has_tier: idx < P.tiers.length, tier_idx: idx, tier_attempt: 1, probe: false, reserved: false, warnings: [] };
if (out.has_tier) {
  const t = P.tiers[idx];
  out.tier_name = t.name; out.paid = t.paid;
  // Worst case this call could cost, reserved up front: prompt tokens estimate + the full max_tokens allowance.
  out.reserve_amount = Math.ceil((P.est_in_tokens * t.price_in + P.request.max_tokens * t.price_out) / 1e6 * 1e8) / 1e8;
}
return [{ json: out }];

const C = $('CONFIG').first().json;
const S = $('Plan Step').last().json;
const proceed = (extra = {}) => [{ json: { ...S, ...extra, route: 'proceed' } }];
if (!C.BREAKER_ENABLED) return proceed();
const r = $input.first().json;
const b = r.statusCode === 200 && r.body && typeof r.body === 'object' ? r.body : null;
if (!b || !['closed', 'open'].includes(b.status)) return proceed({ warnings: ['breaker_unavailable_fail_open'] });   // a dead breaker service must not take the router down
if (b.status === 'closed') return proceed();
const due = b.next_probe_at === null || b.next_probe_at === undefined || Date.now() >= Number(b.next_probe_at);
if (due) return [{ json: { ...S, route: 'claim' } }];
return [{ json: { ...S, route: 'skip', record: { tier: S.tier_name, outcome: 'skipped', reason: 'breaker_open' } } }];

const S = $('Breaker Verdict').last().json;
const r = $input.first().json;
const claimed = r.statusCode === 200 && r.body && r.body.claimed === true;
if (claimed) return [{ json: { ...S, probe: true, route: 'proceed' } }];
return [{ json: { ...S, route: 'skip', record: { tier: S.tier_name, outcome: 'skipped', reason: 'breaker_open' } } }];

const C = $('CONFIG').first().json;
const S = $('Budget Needed?').last().json;
const r = $input.first().json;
const b = r.statusCode === 200 && r.body && typeof r.body === 'object' ? r.body : null;
if (b && b.granted === true) return [{ json: { ...S, reserved: true, route: 'proceed' } }];
if (b && b.granted === false) return [{ json: { ...S, route: 'skip', record: { tier: S.tier_name, outcome: 'skipped', reason: 'budget_denied' } } }];
// The budget service itself failed. Default is to protect the money (closed); 'open' keeps serving but cannot enforce the limit.
if (C.BUDGET_FAIL_MODE === 'open') return [{ json: { ...S, route: 'proceed', warnings: [...(S.warnings || []), 'budget_unavailable_fail_open'] } }];
return [{ json: { ...S, route: 'skip', record: { tier: S.tier_name, outcome: 'skipped', reason: 'budget_unavailable' } } }];

const P = $('Validate Request').first().json.plan;
const S = $input.first().json;
const t = P.tiers[S.tier_idx], q = P.request;
const sys = [q.system, q.require_json ? 'Respond with a single valid JSON value and nothing else: no prose, no code fences.' : null].filter((x) => x).join('\n\n') || null;
const headers = { 'content-type': 'application/json' };
let body;
if (t.kind === 'ollama') {
  body = { model: t.model, prompt: q.prompt, stream: false, options: { num_predict: q.max_tokens } };
  if (sys) body.system = sys;
  if (t.api_key) headers.authorization = 'Bearer ' + t.api_key;
} else if (t.kind === 'openai') {
  body = { model: t.model, max_tokens: q.max_tokens, messages: [...(sys ? [{ role: 'system', content: sys }] : []), { role: 'user', content: q.prompt }] };
  if (t.api_key) headers.authorization = 'Bearer ' + t.api_key;
} else {
  body = { model: t.model, max_tokens: q.max_tokens, messages: [{ role: 'user', content: q.prompt }] };
  if (sys) body.system = sys;
  headers['anthropic-version'] = t.anthropic_version;
  if (t.api_key) headers['x-api-key'] = t.api_key;
}
Object.assign(headers, t.headers);
return [{ json: { ...S, call: { url: t.url, headers, body, timeout_ms: t.timeout_ms }, started_ms: Date.now() } }];

const C = $('CONFIG').first().json;
const P = $('Validate Request').first().json.plan;
const S = $('Build Call').last().json;
const t = P.tiers[S.tier_idx], q = P.request;
const r = $input.first().json;
const latency_ms = Date.now() - S.started_ms;

let status = 'hard_failure', reason = null, health = 'failure', retriable = false, text = null, parsed, usage = null, http_status = r.statusCode === undefined ? null : r.statusCode;
const hasStatus = typeof r.statusCode === 'number';
if (!hasStatus) {                                                    // no HTTP answer at all: refused, DNS, timeout
  const m = r.error && (r.error.message || r.error.description || r.error);
  reason = 'network_error: ' + String(m || 'no response').slice(0, 200); retriable = true;
} else if (r.statusCode >= 500 || r.statusCode === 429 || r.statusCode === 408) {
  reason = 'http_' + r.statusCode; retriable = true;
} else if ([401, 403, 404].includes(r.statusCode)) {
  reason = 'http_' + r.statusCode + '_check_url_or_key';             // our configuration is wrong; retrying cannot help
} else if (r.statusCode >= 400) {
  status = 'rejected'; health = 'none'; reason = 'http_' + r.statusCode + '_request_rejected';   // the provider is up but refused this request: not its health problem
} else {
  const b = r.body;
  let extracted = null, u = null;
  if (b && typeof b === 'object') {
    if (t.kind === 'ollama' && typeof b.response === 'string') { extracted = b.response; u = { i: b.prompt_eval_count, o: b.eval_count }; }
    else if (t.kind === 'openai' && Array.isArray(b.choices) && b.choices.length) {
      const c = b.choices[0] && b.choices[0].message && b.choices[0].message.content;
      extracted = typeof c === 'string' ? c : ''; u = b.usage ? { i: b.usage.prompt_tokens, o: b.usage.completion_tokens } : null;
    } else if (t.kind === 'anthropic' && Array.isArray(b.content)) {
      extracted = b.content.filter((x) => x && x.type === 'text' && typeof x.text === 'string').map((x) => x.text).join(''); u = b.usage ? { i: b.usage.input_tokens, o: b.usage.output_tokens } : null;
    }
  }
  if (extracted === null) { reason = 'unexpected_response_shape_for_' + t.kind; }       // 2xx but not the format this tier is configured as
  else {
    health = 'success';                                                 // the provider answered properly; what follows is about quality, not health
    text = extracted.trim();
    usage = u;
    if (text.length < Math.max(1, C.MIN_RESPONSE_CHARS)) { status = 'soft_failure'; reason = 'empty_response'; }
    else if (q.require_json) {
      const stripped = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
      try { parsed = JSON.parse(stripped); text = stripped; status = 'accepted'; } catch (e) { status = 'soft_failure'; reason = 'invalid_json'; }
    } else status = 'accepted';
  }
}
// ---- cost: only calls that produced a response cost anything
let cost_usd = 0, tokens_in = 0, tokens_out = 0;
if (text !== null) {
